function sumDown(n):
  if n <= 0: return 0
  return n + sumDown(n - 1)

function count(n):
  if n <= 1: return 1
  return count(n - 1) + count(n - 2)

function reduce(n):
  if n <= 0: return 0
  return n + reduce(n - 2)
